import org.junit.jupiter.api.io.TempDir;

class ValueStoreDatatypeCacheConcurrencyTest {

	@Test
	@Timeout(30)
	void concurrentCollisionsNeverReturnAnotherDatatype(@TempDir File directory) throws Exception {
		ValueStore store = new ValueStore(directory, new LmdbStoreConfig());
		try {
			DatatypePair pair = collidingDatatypes(store);
			AtomicBoolean finished = new AtomicBoolean();
			CountDownLatch started = new CountDownLatch(1);
			try (var executor = Executors.newFixedThreadPool(2)) {
				var writer = executor.submit(() -> {
					started.countDown();
					while (!finished.get()) {
						store.cacheDatatype(pair.coreId(), pair.core());
						store.cacheDatatype(pair.customId(), pair.custom());
					}
				});
				try {
					started.await();
					for (int i = 0; i < 1_000_000; i++) {
						assertCoreDatatypeIfPresent(store, pair.coreId(), CoreDatatype.XSD.INT);
						assertCoreDatatypeIfPresent(store, pair.customId(), CoreDatatype.NONE);
					}
				} finally {
					finished.set(true);
					writer.get();
				}
			}
		} finally {
			store.close();
		}
	}

	@Test
	void replacementKeepsDatatypeAndCoreDatatypeTogether(@TempDir File directory) throws Exception {
		ValueStore store = new ValueStore(directory, new LmdbStoreConfig());
		try {
			DatatypePair pair = collidingDatatypes(store);
			store.cacheDatatype(pair.coreId(), pair.core());
			assertSame(pair.core(), store.cachedDatatype(pair.coreId()));
			assertSame(CoreDatatype.XSD.INT, store.cachedDatatypeCoreDatatype(pair.coreId()));
			store.cacheDatatype(pair.customId(), pair.custom());
			assertNull(store.cachedDatatype(pair.coreId()));
			assertNull(store.cachedDatatypeCoreDatatype(pair.coreId()));
			assertSame(pair.custom(), store.cachedDatatype(pair.customId()));
			assertSame(CoreDatatype.NONE, store.cachedDatatypeCoreDatatype(pair.customId()));
			store.cacheDatatype(pair.coreId(), pair.core());
			assertNull(store.cachedDatatype(pair.customId()));
			assertNull(store.cachedDatatypeCoreDatatype(pair.customId()));
			assertSame(pair.core(), store.cachedDatatype(pair.coreId()));
			assertSame(CoreDatatype.XSD.INT, store.cachedDatatypeCoreDatatype(pair.coreId()));
			store.clearCaches();
			assertNull(store.cachedDatatype(pair.coreId()));
			assertNull(store.cachedDatatypeCoreDatatype(pair.coreId()));
		} finally {
			store.close();
		}
	}

	@Test
	@Timeout(30)
	void materializedLiteralsRetainTheirDatatypeDuringReplacement(@TempDir File directory) throws Exception {
		ValueStore store = new ValueStore(directory, new LmdbStoreConfig().setValueCacheSize(1)
				.setInlineLiterals(false));
		try {
			DatatypePair pair = collidingDatatypes(store);
			store.startTransaction(true);
			long coreLiteralId = store.storeValue(store.createLiteral("42", pair.core()));
			long customLiteralId = store.storeValue(store.createLiteral("custom", pair.custom()));
			store.commit();
			AtomicBoolean finished = new AtomicBoolean();
			CountDownLatch started = new CountDownLatch(1);
			try (var executor = Executors.newSingleThreadExecutor()) {
				var writer = executor.submit(() -> {
					started.countDown();
					while (!finished.get()) {
						store.cacheDatatype(pair.coreId(), pair.core());
						store.cacheDatatype(pair.customId(), pair.custom());
					}
				});
				try {
					started.await();
					for (int i = 0; i < 10_000; i++) {
						Literal core = (Literal) store.getValue(coreLiteralId);
						Literal custom = (Literal) store.getLazyValue(customLiteralId);
						assertEquals(pair.core(), core.getDatatype());
						assertSame(CoreDatatype.XSD.INT, core.getCoreDatatype());
						assertEquals(pair.custom(), custom.getDatatype());
						assertSame(CoreDatatype.NONE, custom.getCoreDatatype());
					}
				} finally {
					finished.set(true);
					writer.get();
				}
			}
		} finally {
			store.close();
		}
	}

	private static void assertCoreDatatypeIfPresent(ValueStore store, long id, CoreDatatype expected) {
		CoreDatatype actual = store.cachedDatatypeCoreDatatype(id);
		if (actual != null) {
			assertSame(expected, actual, "Cached core datatype must belong to the requested stored ID " + id);
		}
	}

	private static DatatypePair collidingDatatypes(ValueStore store) throws Exception {
		long coreId = store.getId(CoreDatatype.XSD.INT.getIri());
		long customId;
		store.startTransaction(true);
		int ordinal = 0;
		do {
			customId = store.storeValue(store.createIRI("urn:datatype-cache:custom:" + ordinal++));
		} while ((ValueIds.getValue(customId) & 1023) != (ValueIds.getValue(coreId) & 1023));
		store.commit();
		LmdbIRI core = (LmdbIRI) store.getValue(coreId);
		LmdbIRI custom = (LmdbIRI) store.getValue(customId);
		assertEquals(CoreDatatype.XSD.INT.getIri(), core);
		assertSame(CoreDatatype.NONE, CoreDatatype.from(custom));
		return new DatatypePair(coreId, core, customId, custom);
	}

	private record DatatypePair(long coreId, LmdbIRI core, long customId, LmdbIRI custom) {
	}
}
